/* Quantōrum Fabellae - March 2022 */

let W = 500, H = 500; // default

let QUnder = [];
let QBars = [];
let QPath = [];

function setup() {
	startTime = (new Date()).getTime();
	createCanvas(windowHeight, windowHeight);
	W = windowHeight;
	H = windowHeight;
	noFill();
	stroke(0);
	background(255);
	angleMode(DEGREES)
	center = createVector(W*0.5, H*0.5);
	QUnder = CreateTheUndergrounds();
	QPath = CreateQPath();
	QBars = CreateBars(Math.floor(QPath.length / 14));
	DrawArtwork();
}
function CreateQPath() {
	let QPoints = []; // all polar positions
	let polarPos = createVector( // current polar position
		R.random_num(0,360), // angle
		R.random_num(0,W*0.3)+W*0.1); // radius
	let QP1 = [];
	QP1.push(polarPos);
	QP1.push(polarPos.copy()); // original polar position
	QP1.push(R.random_num(2,16));
	QP1.push(R.random_num(0,140)); // stroke color (GRAY)
	QPoints.push(QP1); // first point

	for(i=0; i<3*(R.random_num(0,8)+4); i++) {
		let QPoint = [];
		let pos = polarToCart(polarPos.x, polarPos.y);
		let newPolarPos = polarPos.copy(); // new target polar position
		if(i%2 == 0) {
			newPolarPos.y = R.random_num(0.0,W*0.35)+W*0.1;
			polarPos = newPolarPos;
			QPoint.push(polarPos);
			QPoint.push(polarPos.copy()); // original polar position
		} else {
			newPolarPos.x = R.random_num(0,360);
			polarPos = newPolarPos;
			QPoint.push(polarPos);
			QPoint.push(polarPos.copy()); // original polar position
		}
		stroke_weight = R.random_num(2,16);
		QPoint.push(stroke_weight);
		QPoint.push(R.random_num(0,140)); // stroke color (GRAY)
		QPoints.push(QPoint);
	}
	return QPoints;
}

function DrawQPath(_QPoints) {
	for(i=0; i<_QPoints.length-1; i++) {
		var QPoint = _QPoints[i];
		let polarPoint = QPoint[0];
		var pos = polarToCart(polarPoint.x, polarPoint.y);
		let nextPolarPoint = _QPoints[i+1][0];
		let nextPos = polarToCart(nextPolarPoint.x, nextPolarPoint.y);
		stroke(255,127,0);
		circle(pos.x,pos.y,3);
		stroke(QPoint[3]);
		strokeWeightRel(QPoint[2]); // stroke weight
		if(i%2 == 0) {
			line(pos.x, pos.y, nextPos.x, nextPos.y);
		} else {
			arc(W*0.5,H*0.5, polarPoint.y*2, polarPoint.y*2, polarPoint.x, nextPolarPoint.x);
		}

	}
}

function CreateTheUndergrounds(){
	let undergrounds = [];
	let c = color(0);
	for(i=0; i<16; i++) {
		let underground = [];
		if(i%2==0)
			c = color(100,100,100,50);
		else
			c = color(255);
		var steps = 1+R.random_num(0,4);
		underground.push(steps);
		var a_r = 2*(R.random_num(0.0,W*0.28)+W*0.15);
		underground.push(a_r);
		var arand1 = R.random_num(0,360);
		underground.push(arand1);
		var arand2 = R.random_num(0,360);
		underground.push(arand2);
		var a_start = min(arand1,arand2);
		underground.push(a_start);
		var a_end = max(arand1,arand2);
		underground.push(a_end);
		underground.push(32+R.random_num(0,32)); // stroke weight
		undergrounds.push(underground);
	}
	return undergrounds;
}

function DrawTheUndergrounds(_undergrounds) {
	var c = color(0);
	for(i=0; i<_undergrounds.length; i++) {
		let u = _undergrounds[i];
		var steps = u[0];
		var a_r = u[1];
		var arand1 = u[2];
		var arand2 = u[3];
		var a_start = u[4];
		var a_end = u[5];
		var stroke_w = u[6];
		if(i%2==0)
			c = color(100,100,100,50);
		else
			c = color(255);
		drawStepBar(a_start, a_end, a_r, steps, stroke_w, c);
	}
}

function drawStepBar(_start, _end, _r, _steps, _strokeWeight, _color) {
	stroke(_color.levels[0], _color.levels[1], _color.levels[2], _color.levels[3]);
	strokeWeightRel(_strokeWeight);
	strokeCap(SQUARE);
	let steps = _steps;
	let a_r = _r;
	let a_start = _start;
	let a_end = _end;
	let a_diff = a_end - a_start;
	let a_step = a_diff / steps;
	let a_half_step = a_step*0.5;
	for(a=0; a<steps; a++){
		arc(W*0.5, H*0.5, a_r, a_r,
			a_start + a_step*a-a_step*0.5,
			a_start + a_step*a)
	}
	strokeCap(ROUND);

}
function CreateBars(_Nbars) {
	let bars = [];
	for(i=0; i<_Nbars; i++) {
		bars.push(CreateBar());	
	}
	return bars;
}
function CreateBar() {
	let bar = [];
	var steps = 5+R.random_num(0,15);
	bar.push(steps);
	var a_r = 2*(R.random_num(0.0,W*0.3)+W*0.15);
	bar.push(a_r);
	let arand1 = R.random_num(0,360);
	bar.push(arand1);
	let arand2 = R.random_num(0,360);
	bar.push(arand2);
	var a_start = min(arand1,arand2);
	bar.push(a_start);
	var a_end = max(arand1,arand2);
	bar.push(a_end);
	let str_weight = 4+R.random_num(0,24);
	bar.push(str_weight);
	return bar;
}
function DrawBars(_bars) {
	var c = color(255,127,0);
	for(i=0; i<_bars.length; i++) {
		var bar = _bars[i];
		var steps = bar[0];
		var a_r = bar[1];
		var arand1 = bar[2];
		var arand2 = bar[3];
		var a_start = bar[4];
		var a_end = bar[5];
		var str_weight = bar[6];
		drawStepBar(a_start, a_end, a_r, steps, str_weight, c);
	}
}

