function DrawArtwork() {
	background(255);
	DrawTheUndergrounds(QUnder);
	DrawQPath(QPath);
	DrawBars(QBars);
	//DrawOrigPositions();
}

// stroke weight relative to original 500x500 resolution (Width)
function strokeWeightRel(_w) {
	strokeWeight( W*(_w/500) );
}

function polarToCart(_angle, _r) {
	return createVector(
		_r * cos(_angle) + W*0.5,
		_r * sin(_angle) + H*0.5
	);
}

function keyPressed() {
	if(key=='r' || key=='R'){
		QUnder = CreateTheUndergrounds();
		QPath = CreateQPath();
		QBars = CreateBars(Math.floor(QPath.length / 14));
		DrawArtwork();
	}
}

function mouseClicked() {
	QUnder = CreateTheUndergrounds();
	QPath = CreateQPath();
	QBars = CreateBars(Math.floor(QPath.length / 14));
	DrawArtwork();
}


